INSERT INTO `whatsapp_settings` (`id`, `texto_para_cadastro`, `texto_referencia_cobranca`, `voz_padrao`, `created_at`, `updated_at`) VALUES 
('3', 'Juntos somos mais fortes!  Faça parte da Associação dos Ribeirinhos do Porto Cercado. Cadastre-se, fortaleça nossa união e ajude a construir um futuro melhor para nossa comunidade.', '{nome}, tudo bem? A Associação segue trabalhando e buscando melhorias para todos. Sua mensalidade é parte essencial desse trabalho. Identificamos uma contribuição pendente e contamos muito com você para continuarmos avançando.  {nome}, muito obrigado de coração.  Digite 2 que te ajudo na quitação.', 'pt-BR-FranciscaNeural', '2026-09-03 17:47:09', '2026-09-06 09:39:35');
